// The 9.3 admin scoping surface (bind / adopt / explain) — black-box over the
// REAL router and the SAME chain production rides (authMiddleware →
// requireRole(RoleAdmin) → handler → viewerFor), the auth_chain_test.go
// harness.

// bindUserPath renders a device id into its admin bind route path.
func bindUserPath(id int64) string {
	return "/api/v1/admin/devices/" + strconv.FormatInt(id, 10) + "/user"
}

// adoptLegacyPath renders a user id into its adopt-legacy route path.
func adoptLegacyPath(id int64) string {
	return "/api/v1/admin/users/" + strconv.FormatInt(id, 10) + "/adopt-legacy"
}

// explainPath renders the visibility-explain query route.
func explainPath(userID, libraryID int64) string {
	return "/api/v1/admin/visibility-explain?user_id=" + strconv.FormatInt(userID, 10) +
		"&library_id=" + strconv.FormatInt(libraryID, 10)
}

// mintPairedDevice mints one REAL device credential through the pairing
// flow (the TestAuthChainDevices pattern) and returns the raw bearer token.
func mintPairedDevice(t *testing.T, devices *pairing.Service) string {
	t.Helper()
	ctx := context.Background()
	req, err := devices.CreateRequest(ctx, "10.0.0.1")
	if err != nil {
		t.Fatalf("CreateRequest: %v", err)
	}
	if _, err := devices.Approve(ctx, req.ID); err != nil {
		t.Fatalf("Approve: %v", err)
	}
	out, err := devices.Wait(ctx, req.ID)
	if err != nil || out.Token == "" {
		t.Fatalf("Wait: outcome=%+v err=%v (want the raw device token once)", out, err)
	}
	return out.Token
}

// deviceRowID resolves a raw device bearer token to its credentials rowid —
// the {id} the bind endpoint addresses.
func deviceRowID(t *testing.T, st *store.Store, token string) int64 {
	t.Helper()
	devs, err := st.ListDevices(context.Background())
	if err != nil {
		t.Fatalf("ListDevices: %v", err)
	}
	hash := hashBearerToken(token)
	for _, d := range devs {
		if d.TokenHash == hash {
			id, err := strconv.ParseInt(d.ID, 10, 64)
			if err != nil {
				t.Fatalf("device rowid %q: %v", d.ID, err)
			}
			return id
		}
	}
	t.Fatalf("no credentials row for the minted token %s…", token[:8])
	return 0
}

// decodeDeviceList pulls a devicesResponse out of a 200 response.
func decodeDeviceList(t *testing.T, resp *http.Response) devicesResponse {
	t.Helper()
	var dr devicesResponse
	if err := json.NewDecoder(resp.Body).Decode(&dr); err != nil {
		t.Fatalf("decode devicesResponse: %v", err)
	}
	return dr
}

// decodeExplain pulls an adminVisibilityExplain out of a 200 response.
func decodeExplain(t *testing.T, resp *http.Response) adminVisibilityExplain {
	t.Helper()
	var ex adminVisibilityExplain
	if err := json.NewDecoder(resp.Body).Decode(&ex); err != nil {
		t.Fatalf("decode adminVisibilityExplain: %v", err)
	}
	return ex
}

// userSlotProgress reads one progress row straight out of a ledger slot
// (the adopt assertions need slot-level truth, not a viewer-scoped view).
func userSlotProgress(t *testing.T, st *store.Store, userID int64, itemID string) (int64, bool) {
	t.Helper()
	var pos int64
	err := st.DB().QueryRowContext(context.Background(),
		`SELECT position_seconds FROM playback_progress WHERE user_id = ? AND item_id = ?`,
		userID, itemID).Scan(&pos)
	if err == nil {
		return pos, true
	}
	return 0, false
}

// userSlotCompletedAt reads one watched row's completion stamp from a slot.
func userSlotCompletedAt(t *testing.T, st *store.Store, userID int64, itemID string) (time.Time, bool) {
	t.Helper()
	var stamp string
	err := st.DB().QueryRowContext(context.Background(),
		`SELECT completed_at FROM watched_items WHERE user_id = ? AND item_id = ?`,
		userID, itemID).Scan(&stamp)
	if err != nil {
		return time.Time{}, false
	}
	ts, err := time.Parse(time.RFC3339Nano, stamp)
	if err != nil {
		t.Fatalf("completed_at %q: %v", stamp, err)
	}
	return ts, true
}

// TestAdminBindAdoptExplain pins the 9.3 surface end to end: the bind
// re-scope / unbind revert through REAL bearer requests (the 7.1 chain
// live), the bind validations, the one-shot newer-wins adopt with the
// no-op rerun, and the explain answers over the one ResolveViewer set.
func TestAdminBindAdoptExplain(t *testing.T) {
	ctx := context.Background()

	t.Run("bind_re-scopes_and_unbind_reverts", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		devices := pairing.NewService(st, nil)
		u, err := ident.Create(ctx, "petra", "pw")
		if err != nil {
			t.Fatalf("identity.Create petra: %v", err)
		}
		granted, hidden := seedGrantedLibrary(t, ident, st, "petra")
		token := mintPairedDevice(t, devices)
		id := deviceRowID(t, st, token)
		h := authChainRouter(t, st, ident)

		// BEFORE the bind: the unbound device rides the legacy see-all
		// viewer (a live accounts deployment — petra exists — but the
		// credential is unbound).
		ids := listedLibraryIDs(t, doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", token))
		if !ids[granted] || !ids[hidden] {
			t.Fatalf("unbound device list = %v, want see-all ({%d, %d})", ids, granted, hidden)
		}

		// Bind through the ENDPOINT (7.1 seeded this row by raw SQL; here the
		// surface under test writes it).
		bind := doRequest(t, h, http.MethodPut, bindUserPath(id), `{"user_id":`+
			strconv.FormatInt(u.ID, 10)+`}`, adminToken)
		bind.Body.Close()
		if bind.StatusCode != http.StatusNoContent {
			t.Fatalf("bind = %d, want 204", bind.StatusCode)
		}

		// The SAME bearer, next request: exactly the bound user's grant —
		// the 7.1 chain live, no re-pair, no session.
		ids = listedLibraryIDs(t, doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", token))
		if !ids[granted] || ids[hidden] || len(ids) != 1 {
			t.Fatalf("bound device list = %v, want exactly the grant {%d}", ids, granted)
		}

		// The device list carries the posture (the device-pairing spec's
		// "both states visible on the device list").
		list := doRequest(t, h, http.MethodGet, "/api/v1/admin/devices", "", adminToken)
		dr := decodeDeviceList(t, list)
		list.Body.Close()
		var listed *deviceDTO
		for i := range dr.Devices {
			if dr.Devices[i].DeviceID == strconv.FormatInt(id, 10) {
				listed = &dr.Devices[i]
			}
		}
		if listed == nil || listed.UserID != u.ID {
			t.Fatalf("device list posture = %+v, want user_id %d on device %d",
				dr.Devices, u.ID, id)
		}

		// Unbind (null): the legacy see-all returns, and the list reads 0.
		unbind := doRequest(t, h, http.MethodPut, bindUserPath(id), `{"user_id":null}`, adminToken)
		unbind.Body.Close()
		if unbind.StatusCode != http.StatusNoContent {
			t.Fatalf("unbind = %d, want 204", unbind.StatusCode)
		}
		ids = listedLibraryIDs(t, doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", token))
		if !ids[granted] || !ids[hidden] {
			t.Fatalf("unbound device list after unbind = %v, want see-all", ids)
		}
		list2 := doRequest(t, h, http.MethodGet, "/api/v1/admin/devices", "", adminToken)
		dr2 := decodeDeviceList(t, list2)
		list2.Body.Close()
		for _, d := range dr2.Devices {
			if d.DeviceID == strconv.FormatInt(id, 10) && d.UserID != 0 {
				t.Fatalf("device %d posture after unbind = %d, want 0", id, d.UserID)
			}
		}
	})

	t.Run("bind_validation", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		devices := pairing.NewService(st, nil)
		if _, err := ident.Create(ctx, "helga", "pw"); err != nil {
			t.Fatalf("identity.Create helga: %v", err)
		}
		token := mintPairedDevice(t, devices)
		id := deviceRowID(t, st, token)
		h := authChainRouter(t, st, ident)

		// A session credential is NOT a device: its credentials rowid under
		// the bind route is an unknown device (the store's kind='device'
		// guard, surfaced as a 404).
		sess, err := ident.MintSession(ctx, "helga", "pw")
		if err != nil {
			t.Fatalf("MintSession: %v", err)
		}
		var sessRow int64
		if err := st.DB().QueryRowContext(ctx,
			`SELECT id FROM credentials WHERE kind = 'session' AND token_hash = ?`,
			hashBearerToken(sess.Token)).Scan(&sessRow); err != nil {
			t.Fatalf("session credentials row: %v", err)
		}

		for _, tc := range []struct {
			name, path, body string
			code             int
		}{
			{"unknown_device", bindUserPath(99999), `{"user_id":1}`, http.StatusNotFound},
			{"unknown_user", bindUserPath(id), `{"user_id":99999}`, http.StatusNotFound},
			{"session_rowid_is_not_a_device", bindUserPath(sessRow), `{"user_id":1}`, http.StatusNotFound},
			{"non_integer_device_id", "/api/v1/admin/devices/abc/user", `{"user_id":1}`, http.StatusBadRequest},
			{"malformed_body", bindUserPath(id), `{`, http.StatusBadRequest},
		} {
			resp := doRequest(t, h, http.MethodPut, tc.path, tc.body, adminToken)
			code := resp.StatusCode
			resp.Body.Close()
			if code != tc.code {
				t.Fatalf("%s: PUT %s %q = %d, want %d", tc.name, tc.path, tc.body, code, tc.code)
			}
		}
	})

	t.Run("adopt_newer_wins_and_noop", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		u, err := ident.Create(ctx, "sonya", "pw")
		if err != nil {
			t.Fatalf("identity.Create sonya: %v", err)
		}
		uid := u.ID
		lib := seedLibrary(t, st, "/media/adopt")
		itemA, itemB := "itm_adopt-a", "itm_adopt-b"
		seedItem(t, st, lib, "adopt-a", "a.mkv")
		seedItem(t, st, lib, "adopt-b", "b.mkv")
		h := authChainRouter(t, st, ident)

		// Seed the two ledger slots through the REAL viewer-scoped store
		// writes (the 9.1 precedent): the user's rows into her slot, the
		// legacy rows into slot 0, with the write order deciding the
		// newer/older sides per item.
		uview := access.User(uid, []int64{lib}, nil)
		userOlder := time.Now().UTC().Add(-2 * time.Hour)
		userNewer := time.Now().UTC().Add(-1 * time.Hour)
		// Item A: the LEGACY rows are newer on both tables (they win).
		if _, err := st.PutProgress(ctx, itemA, 100, uview); err != nil {
			t.Fatalf("PutProgress user A: %v", err)
		}
		if err := st.InsertWatched(ctx, itemA, lib, "", userOlder, uview); err != nil {
			t.Fatalf("InsertWatched user A: %v", err)
		}
		if _, err := st.PutProgress(ctx, itemA, 250, access.LegacyDevice()); err != nil {
			t.Fatalf("PutProgress legacy A: %v", err)
		}
		if err := st.InsertWatched(ctx, itemA, lib, "", userNewer, access.LegacyDevice()); err != nil {
			t.Fatalf("InsertWatched legacy A: %v", err)
		}
		// Item B: the USER's rows are newer (they survive).
		if _, err := st.PutProgress(ctx, itemB, 50, access.LegacyDevice()); err != nil {
			t.Fatalf("PutProgress legacy B: %v", err)
		}
		if err := st.InsertWatched(ctx, itemB, lib, "", userOlder, access.LegacyDevice()); err != nil {
			t.Fatalf("InsertWatched legacy B: %v", err)
		}
		if _, err := st.PutProgress(ctx, itemB, 75, uview); err != nil {
			t.Fatalf("PutProgress user B: %v", err)
		}
		if err := st.InsertWatched(ctx, itemB, lib, "", userNewer, uview); err != nil {
			t.Fatalf("InsertWatched user B: %v", err)
		}

		// Adopt through the ENDPOINT: 204, the newer legacy rows land in the
		// user's slot, the newer user rows survive, slot 0 drains.
		adopt := doRequest(t, h, http.MethodPost, adoptLegacyPath(uid), "", adminToken)
		adopt.Body.Close()
		if adopt.StatusCode != http.StatusNoContent {
			t.Fatalf("adopt = %d, want 204", adopt.StatusCode)
		}
		if pos, ok := userSlotProgress(t, st, uid, itemA); !ok || pos != 250 {
			t.Fatalf("user slot %s position = %d (present %t), want the newer legacy 250", itemA, pos, ok)
		}
		if pos, ok := userSlotProgress(t, st, uid, itemB); !ok || pos != 75 {
			t.Fatalf("user slot %s position = %d (present %t), want the surviving user row 75", itemB, pos, ok)
		}
		stampA, ok := userSlotCompletedAt(t, st, uid, itemA)
		if !ok || !stampA.After(userOlder) {
			t.Fatalf("user slot %s completed_at = %v, want the newer legacy stamp (after %v)", itemA, stampA, userOlder)
		}
		stampB, ok := userSlotCompletedAt(t, st, uid, itemB)
		if !ok || !stampB.Equal(userNewer) {
			t.Fatalf("user slot %s completed_at = %v, want the surviving user stamp %v", itemB, stampB, userNewer)
		}
		if n := countRows(t, st, `SELECT COUNT(*) FROM playback_progress WHERE user_id = 0`); n != 0 {
			t.Fatalf("slot-0 progress rows survived the adopt: %d", n)
		}
		if n := countRows(t, st, `SELECT COUNT(*) FROM watched_items WHERE user_id = 0`); n != 0 {
			t.Fatalf("slot-0 watched rows survived the adopt: %d", n)
		}

		// SECOND adopt: a no-op — the slot is drained, values stay put.
		adopt2 := doRequest(t, h, http.MethodPost, adoptLegacyPath(uid), "", adminToken)
		adopt2.Body.Close()
		if adopt2.StatusCode != http.StatusNoContent {
			t.Fatalf("second adopt = %d, want 204 (no-op)", adopt2.StatusCode)
		}
		if pos, _ := userSlotProgress(t, st, uid, itemA); pos != 250 {
			t.Fatalf("position after rerun = %d, want unchanged 250", pos)
		}
		if n := countRows(t, st, `SELECT COUNT(*) FROM playback_progress WHERE user_id = ?`, uid); n != 2 {
			t.Fatalf("user progress rows after rerun = %d, want 2", n)
		}

		// Refusals: unknown user 404, non-integer id 400.
		for _, tc := range []struct {
			path string
			code int
		}{
			{adoptLegacyPath(99999), http.StatusNotFound},
			{"/api/v1/admin/users/abc/adopt-legacy", http.StatusBadRequest},
		} {
			resp := doRequest(t, h, http.MethodPost, tc.path, "", adminToken)
			code := resp.StatusCode
			resp.Body.Close()
			if code != tc.code {
				t.Fatalf("POST %s = %d, want %d", tc.path, code, tc.code)
			}
		}
	})

	t.Run("explain_grants", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		u, err := ident.Create(ctx, "tova", "pw")
		if err != nil {
			t.Fatalf("identity.Create tova: %v", err)
		}
		uid := u.ID
		solo, err := ident.Create(ctx, "solo", "pw")
		if err != nil {
			t.Fatalf("identity.Create solo: %v", err)
		}
		uidSolo := solo.ID
		carried := seedLibrary(t, st, "/media/explain-carried")
		other := seedLibrary(t, st, "/media/explain-other")
		if _, err := ident.CreateGroup(ctx, "Carry"); err != nil {
			t.Fatalf("CreateGroup Carry: %v", err)
		}
		if err := ident.AddCollection(ctx, "Carry", carried, 5); err != nil {
			t.Fatalf("AddCollection: %v", err)
		}
		if err := ident.AddUser(ctx, "Carry", "tova"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}
		// tova's second group carries nothing (exercises the grant walk's
		// skip); the mute document rides the carrying group.
		if _, err := ident.CreateGroup(ctx, "Empty"); err != nil {
			t.Fatalf("CreateGroup Empty: %v", err)
		}
		if err := ident.AddUser(ctx, "Empty", "tova"); err != nil {
			t.Fatalf("AddUser Empty: %v", err)
		}
		if err := ident.SetGroupDoc(ctx, "Carry", `{"mutes":{"com.example.plex":true}}`, 1); err != nil {
			t.Fatalf("SetGroupDoc: %v", err)
		}
		h := authChainRouter(t, st, ident)

		// Carried grant: visible, the carrying group WITH its position, the
		// full resolved set, and the resolved mute state — one answer over
		// the one ResolveViewer set.
		resp := doRequest(t, h, http.MethodGet, explainPath(uid, carried), "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("explain carried = %d, want 200", resp.StatusCode)
		}
		ex := decodeExplain(t, resp)
		resp.Body.Close()
		if !ex.Visible || ex.UserID != uid || ex.LibraryID != carried {
			t.Fatalf("explain carried = %+v, want visible for user %d library %d", ex, uid, carried)
		}
		if len(ex.GrantingGroups) != 1 || ex.GrantingGroups[0].GroupName != "Carry" ||
			ex.GrantingGroups[0].Position != 5 {
			t.Fatalf("granting groups = %+v, want [Carry at 5] only", ex.GrantingGroups)
		}
		if len(ex.VisibleLibraryIDs) != 1 || ex.VisibleLibraryIDs[0] != carried {
			t.Fatalf("visible set = %v, want [%d]", ex.VisibleLibraryIDs, carried)
		}
		if !ex.ChainMutes["com.example.plex"] || len(ex.ChainMutes) != 1 {
			t.Fatalf("chain mutes = %v, want {com.example.plex:true}", ex.ChainMutes)
		}

		// Ungranted library for a granted user: invisible, empty grant list.
		resp2 := doRequest(t, h, http.MethodGet, explainPath(uid, other), "", adminToken)
		ex2 := decodeExplain(t, resp2)
		resp2.Body.Close()
		if ex2.Visible || len(ex2.GrantingGroups) != 0 {
			t.Fatalf("explain ungranted = %+v, want visible:false, no granting groups", ex2)
		}

		// Empty-set user (in no group): invisible with [] facts — the
		// silent-nothing antidote names it, not a 404.
		resp3 := doRequest(t, h, http.MethodGet, explainPath(uidSolo, carried), "", adminToken)
		ex3 := decodeExplain(t, resp3)
		resp3.Body.Close()
		if ex3.Visible || len(ex3.GrantingGroups) != 0 || len(ex3.VisibleLibraryIDs) != 0 {
			t.Fatalf("explain empty-set user = %+v, want invisible with empty facts", ex3)
		}

		// Unknown library: the live intersection cannot distinguish it from
		// an uncarried grant — visible:false, empty grant list (never a 404;
		// the explain mirrors the viewer's truth, D5's orphan law).
		resp4 := doRequest(t, h, http.MethodGet, explainPath(uid, 424242), "", adminToken)
		ex4 := decodeExplain(t, resp4)
		resp4.Body.Close()
		if ex4.Visible || len(ex4.GrantingGroups) != 0 {
			t.Fatalf("explain unknown library = %+v, want visible:false with empty grants", ex4)
		}

		// Refusals: missing / non-integer params 400, unknown user 404.
		for _, tc := range []struct {
			path string
			code int
		}{
			{"/api/v1/admin/visibility-explain?library_id=1", http.StatusBadRequest},
			{"/api/v1/admin/visibility-explain?user_id=1", http.StatusBadRequest},
			{"/api/v1/admin/visibility-explain", http.StatusBadRequest},
			{"/api/v1/admin/visibility-explain?user_id=abc&library_id=1", http.StatusBadRequest},
			{"/api/v1/admin/visibility-explain?user_id=1&library_id=abc", http.StatusBadRequest},
			{explainPath(99999, carried), http.StatusNotFound},
		} {
			respBad := doRequest(t, h, http.MethodGet, tc.path, "", adminToken)
			code := respBad.StatusCode
			respBad.Body.Close()
			if code != tc.code {
				t.Fatalf("GET %s = %d, want %d", tc.path, code, tc.code)
			}
		}
	})
}
